1	import React from 'react';
2	import {useCurrentFrame,useVideoConfig} from 'remotion';
3	import {FONT,widthOf} from '../../../lib/type';
4	import {useArtDirection} from '../../../lib/artDirection';
5	import {actionProgress,actionWindows,requireAction,requireNarration,type DirectedScene} from '../../../lib/direction';
6	import {PlaceSubject} from '../../PlaceStage';
7	import {LOCATOR_START_S,LOCATOR_END_S} from '../../CountyLocator';
8	import type {FilmRenderProps} from '../../types';
9	import {FloodStationHero,STATION,CUTAWAY_LAMP,podPoint,type Pal,type Pt} from './FloodStationHero';
10	import {StreetHubSupport,PORCH,CASE,MAP_TRACE,mirrorAbout,indexTip} from './StreetHubSupport';
11	
12	/**
13	 * flood-station-v1: UT San Antonio's solar flood station, as the university describes the design.
14	 *
15	 * ONE station and ONE rising waterline carry the film. Water reaches the station's lowest optical
16	 * lens at ankle height, and in the sensing scene it rises past all four lenses, each lighting as the
17	 * waterline crosses it; every lens it has crossed stays lit. The battery bar the sun fills, the
18	 * weather lamps and the amber risk lamp the chip lights stay in their new state for the rest of the
19	 * film, so each later shot of the station carries what earlier shots performed.
20	 *
21	 * FLOOD WATER IS A SURFACE. Every flooded place draws finished reflective water (StreetHubSupport
22	 * `water`): a sky-lit far band, muddy body, and the posts, boots and lamps standing in it mirrored
23	 * about their own waterlines and broken by ripple bands. What stands in water is clipped at its
24	 * waterline, so it rises out of the surface rather than standing on a slab.
25	 *
26	 * A: the yard-first treatment. Flood water in the street tops the limestone curb, spreads across a
27	 * San Antonio yard, reaches the fence post's orange ankle mark (its flagging tag swings as the edge
28	 * arrives) and rises up the rain boots on the porch step while the phone stays dark; the warning
29	 * comes late. Then the station at the curb is found, charged, climbed, crossed lens by lens, opened
30	 * on its post to the chip that lights its large risk lamp and risk bar, set against a dark server
31	 * building across the road that a dashed line never reaches, followed by its radio rings down a
32	 * long street to the hub at its far end and across open country to the hub's mast, read on the
33	 * hub's flood path map by a seated responder, measured on two cards on a curb notice board, read by
34	 * a finger along the blank paper map, and closed at a curb folding table where a technician folds
35	 * the deployment plan into the prototype's closed case and latches it.
36	 * B: the instrument-first treatment. It opens in the water at the post, where the lowest lens goes
37	 * under and lights, and only then cuts to the yard and the late phone. It reads the battery before
38	 * the station, the lenses close, the housing window before the chip, the radio from above before the
39	 * street, the map before the desk, and closes on the same curb table, closer.
40	 *
41	 * Every visible state is a function of the film frame clock and the board's event windows; nothing
42	 * accumulates between frames. The county's region stands behind every exterior shot and the hub's
43	 * window; this episode never paints a full-frame background. The overhead radio and flood path maps
44	 * are wall views in the registry. Disclosed illustration: no installed station, real street, hub,
45	 * dashboard, responder, server, lab, deployment or field result.
46	 */
47	
48	type V='a'|'b';
49	const clamp=(v:number)=>Math.min(1,Math.max(0,v));
50	const lerp=(a:number,b:number,p:number)=>a+(b-a)*p;
51	const ease=(p:number)=>{const q=clamp(p);return q*q*q*(10+q*(-15+6*q));};
52	const mix=(a:Pt,b:Pt,p:number):Pt=>[lerp(a[0],b[0],p),lerp(a[1],b[1],p)];
53	
54	/** The university's reported figure, verbatim from claim c4's quote, and the bar share it sets. */
55	const VALIDATION={text:'98.82%',share:.9882};
56	/** The water level, in station units, that each part of the story leaves behind. The lowest lens
57	 * goes under at ankle height; in the sensing scene the water rises past the fourth. It only rises. */
58	const LEVEL={start:-20,ankle:-60,top:-215};
59	/** Lens lamp from the water level: a lens begins to light as the water reaches its housing and is
60	 * fully lit once the waterline crosses its centre, and it stays lit. */
61	const podLit=(level:number,i:number)=>clamp((STATION.pods[i]+18-level)/18);
62	const DISCLOSURE_FONT=26, DISCLOSURE_MAX=330;
63	function disclosureLines(text:string):string[]{
64	 const words=text.split(' '), lines:string[]=[];let cur='';
65	 for(const w of words){const next=cur?cur+' '+w:w;if(cur&&widthOf(next,DISCLOSURE_FONT,true)>DISCLOSURE_MAX){lines.push(cur);cur=w;}else cur=next;}
66	 if(cur)lines.push(cur);return lines;
67	}
68	
69	const At:React.FC<{p:Pt;s?:number;r?:number;o?:number;children:React.ReactNode}>=({p,s=1,r=0,o=1,children})=>
70	 <g transform={`translate(${p[0]} ${p[1]}) rotate(${r}) scale(${s})`} opacity={o}>{children}</g>;
71	/** A camera: world point f lands on screen point a at scale s. */
72	const Cam:React.FC<{f:Pt;s:number;a?:Pt;children:React.ReactNode}>=({f,s,a=[540,820],children})=>
73	 <g transform={`translate(${a[0]} ${a[1]}) scale(${s}) translate(${-f[0]} ${-f[1]})`}>{children}</g>;
74	/** A subject standing on the region's ground outdoors rides the plate's camera with its base row. */
75	const Grounded:React.FC<{baseY:number;on:boolean;children:React.ReactNode}>=({baseY,on,children})=>
76	 on?<PlaceSubject baseY={baseY}>{children}</PlaceSubject>:<g>{children}</g>;
77	/** Name the drawn group with its board item id, so the board binds what is actually rendered. */
78	const Item:React.FC<{id:string;children:React.ReactNode}>=({id,children})=><g data-item={id}>{children}</g>;
79	/** Draw only the part of a drawing between rows y0 and y1: above a waterline, or a reflection's band. */
80	const Band:React.FC<{k:string;y0?:number;y1:number;children:React.ReactNode}>=({k,y0=-6000,y1,children})=>
81	 <g><defs><clipPath id={'fsband-'+k}><rect x={-6000} y={y0} width={14000} height={Math.max(0,y1-y0)}/></clipPath></defs>
82	  <g clipPath={`url(#fsband-${k})`}>{children}</g></g>;
83	/** A dashed line that stops: two short slashes mark the break where it ends, joined to nothing. */
84	const BreakMark:React.FC<{from:Pt;to:Pt;ink:string}>=({from,to,ink})=>{
85	 const a=Math.atan2(to[1]-from[1],to[0]-from[0]),ux=Math.cos(a),uy=Math.sin(a),nx=-uy,ny=ux;
86	 return <g data-part="line-break">{[10,24].map(o=>{const c:Pt=[to[0]+ux*o,to[1]+uy*o];
87	  return <path key={o} d={`M${c[0]-nx*16-ux*6} ${c[1]-ny*16-uy*6}L${c[0]+nx*16+ux*6} ${c[1]+ny*16+uy*6}`} stroke={ink} strokeWidth={5} strokeLinecap="round"/>;})}</g>;
88	};
89	
90	export const FloodStationFilm:React.FC<FilmRenderProps>=({board,scene,shot,time_s,variant})=>{
91	 const ad=useArtDirection();if(!ad)throw new Error('Flood station film requires the executed art direction profile');
92	 const frame=useCurrentFrame(),{fps}=useVideoConfig(),t=frame/fps;
93	 if(Math.abs(t-time_s)>1e-6)throw new Error('Flood station film must read the single film frame clock');
94	 const pal:Pal=ad.palette, v:V=variant;
95	 const W=actionWindows(board.scenes as unknown as DirectedScene[]);
96	 const win=(id:string)=>requireAction(W,id);
97	 const p=(id:string)=>actionProgress(win(id),t);
98	 /** A treatment-only event: absent in the other treatment, where its view never draws it. */
99	 const pOpt=(id:string,fallback=1)=>W[id]?actionProgress(W[id],t):fallback;
100	 const raw=(w:{start:number;end:number})=>clamp((t-w.start)/(w.end-w.start));
101	 const clause=board.narration_picture!.clauses.find(r=>t>=r.start_s&&t<r.end_s);
102	 const act=clause?.action_id??(shot as typeof shot&{narration_ids?:string[]}).narration_ids?.map(id=>requireNarration(board,id).actionId)[0]??'hold';
103	 const sid=scene.id, at=(s:string)=>sid===s;
104	 const flat=ad.flat_shots?.[sid];
105	 const fr=shot.framing, view=shot.view;
106	 const st=t-scene.start_s;
107	 const exterior=!scene.interior&&fr!=='overhead';
108	
109	 // ---- the performed states, each read from its own event on the film clock ----
110	 const s1e1=p('s1-event-1'), s1e2=p('s1-event-2'), s1e3=p('s1-event-3'), s1e0=pOpt('s1-event-0');
111	 const s2e1=p('s2-event-1'), s2e2=p('s2-event-2'), s2e3=p('s2-event-3');
112	 const s3e1=p('s3-event-1'), s3e2=p('s3-event-2'), s3e3=p('s3-event-3');
113	 const s4e1=p('s4-event-1'), s4e2=p('s4-event-2'), s4e3=p('s4-event-3');
114	 const s5e1=p('s5-event-1'), s5e2=p('s5-event-2'), s5e3=p('s5-event-3');
115	 const s6e1=p('s6-event-1'), s6e2=p('s6-event-2'), s6e3=p('s6-event-3');
116	 const s7e1=p('s7-event-1'), s7e2=p('s7-event-2'), s7e3=pOpt('s7-event-3',0);
117	 const s8e1=p('s8-event-1'), s8e2=p('s8-event-2'), s8e3=p('s8-event-3');
118	 const s9e1=p('s9-event-1'), s9e2=p('s9-event-2'), s9e3=p('s9-event-3');
119	
120	 // ---- the station's carried state. The water only rises and nothing it has done is undone. ----
121	 // B's s1 design detail: the lowest, ankle-height lens goes under on s1-event-0 (no station stands in
122	 // the s1 yard in either treatment). s2: the prototype stands in ankle-deep water. s3: the water rises
123	 // past the second, third and fourth lenses on s3-event-2, and stays there.
124	 const level=at('s1')?lerp(LEVEL.start,LEVEL.ankle,ease(s1e0))
125	  :at('s2')?LEVEL.ankle
126	  :at('s3')?lerp(LEVEL.ankle,LEVEL.top,s3e2)
127	  :LEVEL.top;
128	 const pods=[0,1,2,3].map(i=>podLit(level,i));
129	 const battery=at('s1')?.24:at('s2')?lerp(.24,1,s2e2):1;
130	 const weather=[0,1,2,3].map(k=>at('s1')||at('s2')?0:at('s3')?clamp(s3e3*4.2-k*1.05):1);
131	 const risk=['s1','s2','s3'].includes(sid)?0:at('s4')?s4e2:1;
132	 const station=(o:Partial<{pods:number[];battery:number;sun:number;sunStrength:number;risk:number;weather:number[];transmit:number;window:number;readings:number;wetTo:number;shadow:number}>={})=>
133	  <FloodStationHero part="station" pods={pods} battery={battery} risk={risk} weather={weather} wetTo={level} time={t} {...o}/>;
134	 const tag=(lines:string[],shown:number,o:{tone?:'ink'|'accent'|'paper';side?:'left'|'right';scale?:number;drop?:number;size?:number}={})=>
135	  shown<=0?null:<g transform={`translate(0 ${-40*(o.scale??1)*(1-ease(shown))})`} opacity={clamp(shown*3)}>
136	   <FloodStationHero part="tag" lines={lines} pal={pal} tone={o.tone} side={o.side} scale={o.scale} drop={o.drop} size={o.size}
137	    swing={10*(1-ease(shown))*(o.side==='left'?1:-1)}/></g>;
138	 /** A station standing in water at base b, scale s: clipped at its waterline, mirrored below it. */
139	 const wading=(k:string,b:Pt,s:number,node:React.ReactNode,depth=-level*s,below=900)=>{
140	  const wl=b[1]-depth;
141	  return {wl,obj:depth>0?<Band k={k+'o'} y1={wl}>{node}</Band>:node,
142	   refl:depth>0?<Band k={k+'r'} y0={wl} y1={wl+below}>{mirrorAbout(wl,<Band k={k+'m'} y1={wl}>{node}</Band>)}</Band>:null};
143	 };
144	
145	 // ---- the disclosure chip; it names the county map only while the locator card is on screen ----
146	 const sceneList=board.scenes as unknown as {id:string;production_disclosure?:string}[];
147	 const namesMap=(d?:string)=>/\bMap\b/.test(d??'');
148	 const mapShown=t>LOCATOR_START_S&&t<LOCATOR_END_S;
149	 const plain=sceneList.find(s=>s.production_disclosure&&!namesMap(s.production_disclosure))?.production_disclosure??'Illustration';
150	 const mapped=sceneList.find(s=>namesMap(s.production_disclosure))?.production_disclosure;
151	 const own=scene.production_disclosure??'Illustration';
152	 const disclosureText=mapShown&&mapped?mapped:namesMap(own)?plain:own;
153	 const dLines=disclosureLines(disclosureText);
154	 const dW=Math.max(...dLines.map(l=>widthOf(l,DISCLOSURE_FONT,true)))+34, dH=dLines.length*32+24;
155	 const disclosure=<g data-disclosure="production_disclosure">
156	  <rect x={44} y={132} width={dW} height={dH} rx={16} fill={pal.paper} opacity={.93}/>
157	  {dLines.map((l,i)=><text key={i} x={60} y={164+i*32} fontFamily={FONT.body} fontSize={DISCLOSURE_FONT} fontWeight={700} fill={pal.ink}>{l}</text>)}
158	 </g>;
159	
160	 // ---- the curbside world: far verge, a street, the limestone curb and the yard, or all of it under
161	 // the risen water once the sensing scene has passed ----
162	 type Curbside={curbY:number;streetTop:number;water?:{front:number}|'flooded';grounded:boolean;reflect?:React.ReactNode};
163	 const curbside=(o:Curbside)=>{
164	  const g=o.grounded;
165	  if(o.water==='flooded')return <g data-world="curbside-flooded"><Grounded baseY={o.curbY+40} on={g}>
166	   <rect x={-60} y={o.streetTop-22} width={1200} height={26} fill="#8D9358"/>
167	   <StreetHubSupport part="water" x0={-60} x1={1140} y={o.streetTop} depth={1990-o.streetTop} t={t} edge="straight" reflect={o.reflect}/>
168	  </Grounded></g>;
169	  return <g data-world="curbside">
170	   <Grounded baseY={o.curbY+40} on={g}>
171	    <rect x={-60} y={o.streetTop-18} width={1200} height={22} fill="#8D9358"/>
172	    <StreetHubSupport part="street" x0={-60} x1={1140} yFar={o.streetTop} yNear={o.curbY} t={t}/>
173	    {o.water&&<StreetHubSupport part="water" x0={-60} x1={1140} y={o.streetTop+4} depth={o.curbY-o.streetTop-2} t={t} edge="straight" opacity={.92}/>}
174	    <StreetHubSupport part="curb" x0={-60} y0={o.curbY} x1={1140} y1={o.curbY-6} h={20}/>
175	    <StreetHubSupport part="lawn" d={`M-60 ${o.curbY+20}L1140 ${o.curbY+14}L1140 1980L-60 1980Z`} box={[-60,o.curbY+14,1200,1980-o.curbY]}/>
176	    {o.water&&<StreetHubSupport part="water" x0={-60} x1={1140} y={o.curbY+6} depth={Math.max(8,o.water.front-o.curbY)} t={t} seed={13} reflect={o.reflect}/>}
177	   </Grounded>
178	  </g>;
179	 };
180	 const rain=(op=.3)=><StreetHubSupport part="rain" t={t} w={1240} h={1920} opacity={op}/>;
181	 const ring=(x:number,y:number,w:number)=><StreetHubSupport part="waterline" x={x} y={y} w={w} t={t}/>;
182	
183	 let pic:React.ReactNode;
184	 switch(view){
185	 case 'street-yard':{
186	  // s1 wide: the university's general example, a San Antonio yard with NO station in it. From the
187	  // first frame the street is full of reflective flood water lapping at the limestone curb. On
188	  // s1-event-1 it tops the curb and spreads across the yard; by about 1.0 s in A its edge has reached
189	  // the chain link post, the orange flagging tag at the ankle mark swings as the edge arrives and the
190	  // waterline climbs to the orange ankle band. On s1-event-2 it rises over the porch's bottom step and
191	  // up the rain boots standing there, while the phone on the porch rail stays dark. Everything that
192	  // stands in the yard is clipped at its waterline and mirrored in the water. A holds and pushes in
193	  // slowly; B arrives on a match cut from the design detail's ankle-height lens to the ankle mark at
194	  // the same screen spot, then pulls back to the whole yard.
195	  const W1=win('s1-event-1'), p1=s1e1;
196	  const curbY=1086, streetTop=1032;
197	  const fence:Pt=[520,1215], fs=1.2, post:Pt=[fence[0]+190*fs,fence[1]];
198	  const porch:Pt=[-30,1250], step=porch[1]-34, rail:Pt=[porch[0]+PORCH.railTop[0],porch[1]+PORCH.railTop[1]];
199	  const boots:Pt=[porch[0]+PORCH.w*.56,step];
200	  const oakAt:Pt=[1000,1150];
201	  const over=clamp(p1/.18);
202	  const front=lerp(curbY+6,1292,clamp(p1/.6))+lerp(0,190,ease(s1e2));
203	  const dFence=33*ease(clamp((p1-.37)/.23))+4*ease(s1e2);
204	  const dPorch=30*ease(clamp((p1-.5)/.1))+44*ease(s1e2);
205	  const dBoots=Math.max(0,dPorch-34);
206	  const dOak=14*ease(clamp((p1-.12)/.3));
207	  const ta=W1.start+.37*(W1.end-W1.start), dt=t-ta;
208	  const sway=dt>0?22*Math.exp(-3*dt)*Math.sin(2*Math.PI*1.6*dt):0;
209	  const fenceNode=<At p={fence} s={fs}><StreetHubSupport part="fence" x0={0} x1={380} h={300} posts={3} mark={1} sway={sway}/></At>;
210	  const porchNode=<At p={porch}><StreetHubSupport part="porch"/></At>;
211	  const bootsNode=<At p={boots}><StreetHubSupport part="boots"/></At>;
212	  const oakNode=<At p={oakAt}><StreetHubSupport part="oak" h={600} seed={9} flip/></At>;
213	  const F=wading('yf',fence,1,fenceNode,dFence,400), Pc=wading('yp',porch,1,porchNode,dPorch,500);
214	  const B=wading('yb',boots,1,bootsNode,dBoots,140), O=wading('yo',oakAt,1,oakNode,dOak,700);
215	  const yardWater=p1>0&&<StreetHubSupport part="water" x0={-60} x1={1140} y={curbY-14*over} depth={front-(curbY-14*over)} t={t} seed={13}
216	   reflect={<g>{O.refl}{F.refl}{Pc.refl}{B.refl}</g>}/>;
217	  const world=<g>
218	   <Item id="s1-water"><Grounded baseY={curbY+40} on={exterior}>
219	    <rect x={-60} y={streetTop-18} width={1200} height={22} fill="#8D9358"/>
220	    <StreetHubSupport part="street" x0={-60} x1={1140} yFar={streetTop} yNear={curbY} t={t}/>
221	    <StreetHubSupport part="water" x0={-60} x1={1140} y={streetTop+3} depth={curbY-streetTop-3+8*over} t={t} edge="straight"/>
222	    <StreetHubSupport part="curb" x0={-60} y0={curbY} x1={1140} y1={curbY-6} h={20}/>
223	    <StreetHubSupport part="lawn" d={`M-60 ${curbY+20}L1140 ${curbY+14}L1140 1980L-60 1980Z`} box={[-60,curbY+14,1200,1980-curbY]}/>
224	    {yardWater}
225	   </Grounded></Item>
226	   <Grounded baseY={oakAt[1]} on={exterior}>{O.obj}</Grounded>
227	   <Grounded baseY={fence[1]} on={exterior}><Item id="s1-post">{F.obj}{dFence>0&&ring(post[0],post[1]-dFence,22)}</Item></Grounded>
228	   <Grounded baseY={porch[1]} on={exterior}>{Pc.obj}
229	    <Item id="s1-boots">{B.obj}{dBoots>0&&ring(boots[0]+60,boots[1]-dBoots,70)}</Item>
230	    <Item id="s1-phone"><At p={[rail[0]+60,rail[1]-10]}><g transform="scale(.3 .11) rotate(90)"><StreetHubSupport part="phone" pal={pal} banner={0} t={t}/></g></At></Item></Grounded>
231	   {rain(.26)}
232	  </g>;
233	  if(v==='a'){
234	   const push=ease(raw({start:shot.start_s,end:shot.start_s+shot.duration_s}));
235	   pic=<Cam f={mix([540,980],[660,1060],push)} s={lerp(1,1.08,push)} a={mix([540,980],[600,1020],push)}>{world}</Cam>;
236	  }else{
237	   const e=ease(raw({start:shot.start_s,end:W1.end}));
238	   pic=<Cam f={mix([post[0],post[1]-31],[540,1000],e)} s={lerp(2.2,1,e)} a={mix([560,1150],[540,1000],e)}>{world}</Cam>;
239	  }
240	  break;}
241	 case 'phone-late':{
242	  // s1 close, looking down at the porch rail's wide cap board. The worn phone lies on it, dark, the
243	  // flood below the balusters; the warning banner slides in only now, after the water is in the yard.
244	  const rot=v==='a'?-10:8, at0:Pt=v==='a'?[540,950]:[560,960];
245	  const balusters=<g>{Array.from({length:6},(_,i)=><rect key={i} x={40+i*180+(v==='a'?0:60)} y={1280} width={34} height={420} fill="#EDE6D6" stroke="#BDB2A0" strokeWidth={2}/>)}</g>;
246	  pic=<g data-world="porch-rail">
247	   <Item id="s1-water"><StreetHubSupport part="water" x0={-60} x1={1140} y={1300} depth={660} t={t} edge="straight"/></Item>
248	   {balusters}
249	   <path d="M-40 700L1120 676L1120 1222L-40 1252Z" fill="#F3EEE3" stroke="#BDB2A0" strokeWidth={3}/>
250	   <path d="M-40 1252L1120 1222L1120 1282L-40 1314Z" fill="#D5CBB8"/>
251	   {[[150,780],[760,1170],[930,760],[300,1200]].map(([x,y],i)=><ellipse key={i} cx={x} cy={y} rx={30+i*8} ry={4} fill="#B8AD98" opacity={.6}/>)}
252	   <path d="M-40 708L1120 684" stroke="#FFFFFF" strokeWidth={3} opacity={.6}/>
253	   <Item id="s1-phone"><At p={at0} s={1.5} r={rot}><g transform="scale(1 .85)">
254	    <Item id="s1-banner"><StreetHubSupport part="phone" pal={pal} banner={s1e3} t={t}/></Item></g></At></Item>
255	   {rain(.22)}
256	  </g>;
257	  break;}
258	 case 'station-wide':{
259	  // s2 wide: the whole prototype station at the curb, standing in ankle-deep water with its lowest lens
260	  // lit, revealed on s2-event-1 while "its researchers built a flood station" is heard. A tilts up from
261	  // the wet foot; B cranes down from the antenna tip to the whole station.
262	  const base:Pt=[500,1300], s=.84;
263	  const S=wading('sw',base,s,<At p={base} s={s}>{station({})}</At>);
264	  const world=<g>
265	   {curbside({curbY:1180,streetTop:1080,water:{front:1460},grounded:exterior,reflect:S.refl})}
266	   <Grounded baseY={base[1]} on={exterior}><Item id="s2-station"><Item id="s2-post"><Item id="s2-panel">{S.obj}</Item></Item></Item>
267	    {ring(base[0]+8,S.wl,34)}
268	    <At p={[base[0]+130,base[1]-860]}>{tag(['Prototype','flood station'],s2e1,{side:'right',drop:30,scale:.9})}</At></Grounded>
269	   {rain(.2)}
270	  </g>;
