382	/** Two-bone reach: shoulder S to a hand target T with segment lengths L1 and L2. The elbow takes the
383	 * lower of the two solutions, as a real arm hangs. Returns elbow, wrist and the forearm angle. */
384	export function reach(S: P, T: P, L1: number, L2: number): {E: P; W: P; deg: number} {
385	 const dx = T[0] - S[0], dy = T[1] - S[1], d0 = Math.hypot(dx, dy) || 1e-6;
386	 const d = Math.min(Math.max(d0, Math.abs(L1 - L2) + 1e-3), L1 + L2 - 1e-3);
387	 const a = Math.atan2(dy, dx), th = Math.acos(Math.min(1, Math.max(-1, (L1 * L1 + d * d - L2 * L2) / (2 * L1 * d))));
388	 const e1: P = [S[0] + L1 * Math.cos(a + th), S[1] + L1 * Math.sin(a + th)];
389	 const e2: P = [S[0] + L1 * Math.cos(a - th), S[1] + L1 * Math.sin(a - th)];
390	 const E = e1[1] >= e2[1] ? e1 : e2;
391	 const W: P = [S[0] + d * Math.cos(a), S[1] + d * Math.sin(a)];
392	 return {E, W, deg: Math.atan2(W[1] - E[1], W[0] - E[0]) * 180 / Math.PI};
393	}
394	const capsule = (a: P, b: P, ra: number, rb: number) => {
395	 const dx = b[0] - a[0], dy = b[1] - a[1], L = Math.hypot(dx, dy) || 1e-6, nx = -dy / L, ny = dx / L;
396	 return `M${a[0] + nx * ra} ${a[1] + ny * ra}L${b[0] + nx * rb} ${b[1] + ny * rb}A${rb} ${rb} 0 0 0 ${b[0] - nx * rb} ${b[1] - ny * rb}L${a[0] - nx * ra} ${a[1] - ny * ra}A${ra} ${ra} 0 0 0 ${a[0] + nx * ra} ${a[1] + ny * ra}Z`;
397	};
