402	export type HandPose = 'open' | 'grip' | 'point' | 'press' | 'pinch' | 'rest' | 'flat';
403	const FINGERS = [{y: -11, l: [13, 11]}, {y: -4, l: [15, 13]}, {y: 3, l: [14, 12]}, {y: 10, l: [11, 9]}];
404	const BEND: Record<HandPose, [number, number][]> = {
405	 open: [[-8, 6], [-2, 6], [4, 6], [10, 8]], grip: [[70, 80], [72, 82], [74, 84], [76, 80]],
406	 point: [[0, 0], [72, 84], [74, 84], [76, 80]], press: [[10, 8], [12, 8], [14, 8], [16, 10]],
407	 pinch: [[38, 42], [60, 70], [66, 74], [70, 76]], rest: [[24, 30], [28, 32], [30, 34], [34, 34]],
408	 flat: [[2, 2], [3, 2], [4, 2], [6, 4]],
409	};
410	/** Finger joints in hand space (wrist at 0,0, pointing along +x). `side` mirrors top and bottom. */
411	function fingerChain(k: number, pose: HandPose, side: 1 | -1): P[] {
412	 const f = FINGERS[k], [b1, b2] = BEND[pose][k];
413	 const base: P = [30, f.y * side];
414	 const a1 = b1 * side * Math.PI / 180, a2 = (b1 + b2) * side * Math.PI / 180;
415	 const j: P = [base[0] + f.l[0] * Math.cos(a1), base[1] + f.l[0] * Math.sin(a1)];
416	 const tip: P = [j[0] + f.l[1] * Math.cos(a2), j[1] + f.l[1] * Math.sin(a2)];
417	 return [base, j, tip];
418	}
419	/** Where the index fingertip lands, in frame space, for a hand at `at` turned `deg`, scale s. */
420	export function indexTip(at: P, deg: number, s: number, pose: HandPose, side: 1 | -1 = 1): P {
421	 const tip = fingerChain(0, pose, side)[2], a = deg * Math.PI / 180;
422	 return [at[0] + s * (tip[0] * Math.cos(a) - tip[1] * Math.sin(a)), at[1] + s * (tip[0] * Math.sin(a) + tip[1] * Math.cos(a))];
