466	   : <ellipse key={i} cx={ex} cy={ey} rx={r * .07} ry={r * .09} fill={SA.line}/>)}
467	  {eyes.map((ex, i) => <path key={'b' + i} d={`M${ex - r * .13} ${ey - r * .2}q${r * .13} ${-r * .07} ${r * .26} 0`} stroke={SA.line} strokeWidth={3} fill="none" strokeLinecap="round"/>)}
468	  {ay < .5
