470	   : <path d={`M${x + sg * r * .96} ${y - .02 * r}q${sg * r * .2} ${r * .2} ${sg * r * .02} ${r * .3}`} fill={skin} stroke={SA.line} strokeWidth={2.4}/>}
471	  <path d={`M${x + yaw * .48 * r - r * .13 * (1 - ay * .4)} ${y + .5 * r}q${r * .13} ${r * .05} ${r * .26 * (1 - ay * .4)} 0`} stroke={SA.line} strokeWidth={2.6} fill="none" strokeLinecap="round"/>
472	 </g>;
473	};
