577	/** A polyline's length, for drawing a path progressively with an exact dash. */
578	const lengthOf = (pts: P[]) => pts.slice(1).reduce((s, q, i) => s + Math.hypot(q[0] - pts[i][0], q[1] - pts[i][1]), 0);
579	const poly = (pts: P[]) => 'M' + pts.map(p => p.map(v => v.toFixed(1)).join(' ')).join('L');
