581	/** The hub's flood path map in screen units w by h: blocks with building footprints, streets, a park,
582	 * the creek with its banks, low points, station dots, orange flood paths that spread along the creek
583	 * and then into the low streets, and dashed higher-risk zones. */
584	const Dashboard: React.FC<{w: number; h: number; dots?: number; paths?: number; zones?: number; t?: number; pal: Pal; header?: boolean}> =
585	 ({w, h, dots = 0, paths = 0, zones = 0, t = 0, pal, header = true}) => {
586	 const id = useUid('sadb');
587	 const r = rng(21);
588	 const X = (u: number) => u * w, Y = (v: number) => v * h;
589	 const creek: P[] = [[-.04, .58], [.14, .55], [.26, .63], [.42, .6], [.55, .69], [.7, .64], [.84, .72], [1.04, .7]].map(([u, v]) => [X(u), Y(v)]);
590	 const streetsX = [.1, .26, .44, .6, .78, .92].map(u => X(u + (r() - .5) * .02));
591	 const streetsY = [.22, .36, .48, .8, .92].map(v => Y(v + (r() - .5) * .02));
592	 const stations: P[] = [[.14, .55], [.33, .62], [.52, .67], [.7, .64], [.88, .72], [.44, .44]].map(([u, v]) => [X(u), Y(v)]);
593	 const low: P[] = [[.27, .8], [.6, .8], [.45, .36]].map(([u, v]) => [X(u), Y(v)]);
594	 // flood paths: along the creek first, then down two low streets and up one, each from a creek point
595	 const routes: {pts: P[]; delay: number; w: number}[] = [
596	  {pts: creek, delay: 0, w: .045},
597	  {pts: [[X(.26), Y(.63)], [X(.26), Y(.8)], [X(.12), Y(.8)]], delay: .35, w: .03},
598	  {pts: [[X(.6), Y(.67)], [X(.6), Y(.8)], [X(.78), Y(.8)]], delay: .45, w: .03},
599	  {pts: [[X(.44), Y(.6)], [X(.44), Y(.48)], [X(.45), Y(.36)]], delay: .6, w: .026},
600	 ];
601	 const spread = clamp(paths);
602	 const zonesPoly: P[][] = [[[.05, .72], [.32, .72], [.34, .88], [.06, .9]], [[.52, .73], [.84, .72], [.86, .87], [.54, .88]], [[.38, .3], [.52, .3], [.52, .52], [.38, .52]]]
603	  .map(z => z.map(([u, v]) => [X(u), Y(v)] as P));
604	 const hd = Math.max(h * .085, 60);
605	 return <g data-part="flood-path-map">
606	  <defs><clipPath id={id}><rect x={0} y={0} width={w} height={h}/></clipPath></defs>
607	  <rect x={0} y={0} width={w} height={h} fill="#E7E2D3"/>
608	  <g clipPath={`url(#${id})`}>
609	   {/* blocks and their building footprints */}
610	   {streetsX.slice(0, -1).map((x0, i) => streetsY.slice(0, -1).map((y0, j) => {const x1 = streetsX[i + 1], y1 = streetsY[j + 1];
611	    return <g key={i + '-' + j}><rect x={x0 + 8} y={y0 + 8} width={x1 - x0 - 16} height={y1 - y0 - 16} rx={4} fill="#DCD5C2"/>
612	     {Array.from({length: 4}, (_, k) => <rect key={k} x={x0 + 14 + (k % 2) * (x1 - x0 - 28) * .5} y={y0 + 14 + Math.floor(k / 2) * (y1 - y0 - 28) * .5}
613	      width={(x1 - x0 - 28) * .38} height={(y1 - y0 - 28) * .34} fill="#C8BFA8"/>)}</g>;}))}
614	   {/* a park along the creek */}
615	   <path d={`M${X(.62)} ${Y(.5)}L${X(.78)} ${Y(.5)}L${X(.8)} ${Y(.62)}L${X(.64)} ${Y(.6)}Z`} fill="#B6C796"/>
616	   {/* streets with casings */}
617	   {streetsX.map((x, i) => <g key={'sx' + i}><path d={`M${x} 0V${h}`} stroke="#B9B09C" strokeWidth={i === 2 ? 18 : 13}/>
618	    <path d={`M${x} 0V${h}`} stroke={i === 2 ? '#F2DCA2' : SA.street} strokeWidth={i === 2 ? 12 : 8}/></g>)}
619	   {streetsY.map((y, i) => <g key={'sy' + i}><path d={`M0 ${y}H${w}`} stroke="#B9B09C" strokeWidth={13}/><path d={`M0 ${y}H${w}`} stroke={SA.street} strokeWidth={8}/></g>)}
620	   {/* the creek: green banks, then water */}
621	   <path d={poly(creek)} stroke="#C2D3B6" strokeWidth={w * .07} fill="none" strokeLinejoin="round" strokeLinecap="round"/>
622	   <path d={poly(creek)} stroke={SA.creek} strokeWidth={w * .022} fill="none" strokeLinejoin="round" strokeLinecap="round"/>
623	   {/* low points, the dips where water collects */}
624	   {low.map(([x, y], i) => <g key={'l' + i}><ellipse cx={x} cy={y} rx={w * .035} ry={w * .022} fill="#7FA6B6" opacity={.55}/>
625	    <ellipse cx={x} cy={y} rx={w * .018} ry={w * .011} fill="#5F8798" opacity={.7}/></g>)}
626	   {/* flood paths spreading, each drawn along its own route from the creek */}
627	   {routes.map((rt, i) => {const g = clamp((spread - rt.delay) / (1 - rt.delay)), L = lengthOf(rt.pts); return g > 0 && <g key={'f' + i}>
628	    <path d={poly(rt.pts)} stroke="#E8812C" strokeWidth={w * rt.w * 1.6} fill="none" strokeLinecap="round" strokeLinejoin="round" opacity={.32}
629	     strokeDasharray={`${L} ${L}`} strokeDashoffset={L * (1 - ease(g))}/>
630	    <path d={poly(rt.pts)} stroke="#D9681C" strokeWidth={w * rt.w * .8} fill="none" strokeLinecap="round" strokeLinejoin="round" opacity={.9}
631	     strokeDasharray={`${L} ${L}`} strokeDashoffset={L * (1 - ease(g))}/></g>;})}
632	   {zones > 0 && zonesPoly.map((z, i) => {const g = clamp(zones * 1.5 - i * .25);
