import json
a=json.load(open("out/dispatch/opening-a.json")); b=json.load(open("out/dispatch/opening-b.json"))
def walk(x,y,path,out):
    if type(x)!=type(y): out.append((path,"TYPE")); return
    if isinstance(x,dict):
        for k in set(x)|set(y):
            if k not in x or k not in y: out.append((path+"/"+k,"MISSING in "+("a" if k not in x else "b"))); continue
            walk(x[k],y[k],path+"/"+k,out)
    elif isinstance(x,list):
        if len(x)!=len(y): out.append((path,"LEN %d %d"%(len(x),len(y)))); 
        for i,(p,q) in enumerate(zip(x,y)): walk(p,q,path+"/%d"%i,out)
    else:
        if x!=y: out.append((path,repr(x)[:80]+" | "+repr(y)[:80]))
out=[];walk(a,b,"",out)
import collections
c=collections.Counter(p.split("/")[1] for p,_ in out)
print(c)
for p,d in out:
    if not p.startswith("/film_direction") and not p.startswith("/scenes"): print(p,d)
EOF'

