/** Bold against regular, measured across both faces at about 1.05x. */
const BOLD = 1.08;

const classOf = (ch: string): keyof typeof EM => {
  if (ch === ' ') return 'space';
  if (ch >= '0' && ch <= '9') return 'digit';
  if (ch >= 'A' && ch <= 'Z') return 'upper';
  if (ch >= 'a' && ch <= 'z') return 'lower';
  return 'punct';
};

/**
 * How wide `s` is, in ems, erring long.
 *
 * Multiply by the font size to get draw units in the frame the text is drawn in.
 */
export function widthEm(s: string, bold = false): number {
  let w = 0;
  for (const ch of s) w += EM[classOf(ch)];
  return bold ? w * BOLD : w;
}

/** Draw units, which is what a caller with a box actually wants to compare against. */
export const widthOf = (s: string, fontSize: number, bold = false) =>
  widthEm(s, bold) * fontSize;

/**
 * Break `s` into lines that each fit `maxUnits` at `fontSize`.
 *
 * A word longer than the whole line is NOT broken mid-word and NOT dropped: it goes
 * on a line of its own and overflows, because a silently truncated warning is worse
 * than an ugly one and a caller needs to be able to see what they did. `overflows`
 * reports it so a gate can refuse it.
 */

/** Measured 25.03% on a phone. Rounded up, plus a point. */
export const FEED_BOTTOM_RESERVE = 0.26;

/** Measured 14.19% on a phone. Rounded up, plus a point. */
export const FEED_RIGHT_RESERVE = 0.15;

/** The lowest y a film may draw its own chrome at, and the rightmost x. Everything the film
 *  puts on screen in screen space is solved against these two rather than against the frame. */
export const SAFE_BOTTOM = Math.round(FRAME_H * (1 - FEED_BOTTOM_RESERVE)); // 1421
export const SAFE_RIGHT = Math.round(FRAME_W * (1 - FEED_RIGHT_RESERVE));   // 918

def overlaps(a0: float, a1: float, b0: float, b1: float) -> bool:
    return a0 < b1 and b0 < a1


def directed_sound_problems(board: dict, sfx: list[dict]) -> list[str]:
    """Check the authored event clock; the mixer verifies and executes WAV samples."""
    import creative_production as creative
    try:
        cues = creative.sound_timeline(board)
    except (KeyError, TypeError, ValueError) as exc:
        return ["directed sound timeline is incomplete: " + str(exc)]
    needed = {cue["id"]: cue for cue in cues if cue["role"] != "quiet"}
    if len({e.get("id") for e in sfx}) != len(sfx) or {e.get("id") for e in sfx} != set(needed):
        return ["sound events must match the directed non-quiet cues exactly"]
    errors = []
    for event in sfx:
        cue = needed[event["id"]]
        prefix = "sound " + event["id"] + ": "
        if event.get("event_id") != cue["event_id"]:
            errors.append(prefix + "file event must bind its directed picture event")
        for key, expected in (("at_s", cue["at_s"]), ("dur_s", cue["duration_s"])):
            if not creative.finite(event.get(key)) or abs(event[key] - expected) > .001:
                errors.append(prefix + key + " differs from the current directed event clock")
        if not creative.finite(event.get("gain")) or not 0 <= event["gain"] <= 1:
            errors.append(prefix + "gain must be finite and between zero and one")
        if not isinstance(event.get("wav"), str) or not event["wav"].strip():
            errors.append(prefix + "needs its source WAV")
        if not creative.concrete(event.get("source") or event.get("provenance"), 20):
            errors.append(prefix + "needs explicit recorded or designed source provenance")
    return errors


def modern_source_binding_problems(board: dict) -> list[str]:
    """Bind the modern route's story claims and optional diagram metadata.

    Executed registered shots/events and fresh art are checked by modern_film;
    rendered meaning still requires the independent exact-film review.
    """
    from daily_production import structure_problems
    errors = structure_problems(board)
