  visual_events?: {id?: string; at_s: number; duration_s?: number; item_ids?: string[];
    motion?: {curve: 'smoothstep'|'linear'|'travel'|'contact'|'landing'; anticipation?: number; settle?: number;free_prop_reason?:string}}[];
