export const techPt=(o:Placed,p:Pt):Pt=>[o.feet[0]+(p[0]-TECH.head[0])*o.s,o.feet[1]+(p[1]-TECH.ground)*o.s];
const techInv=(o:Placed,p:Pt):Pt=>[TECH.head[0]+(p[0]-o.feet[0])/o.s,TECH.ground+(p[1]-o.feet[1])/o.s];
