 <g transform={`translate(${o.feet[0]-TECH.head[0]*o.s} ${o.feet[1]-TECH.ground*o.s}) scale(${o.s})`}>{children}</g>;
const mixP=(a:Pt,b:Pt,p:number):Pt=>[a[0]+(b[0]-a[0])*p,a[1]+(b[1]-a[1])*p];

