// Composed-transform frame-edge bounds for the R15h corrections, every frame of each affected shot in both
// treatments. Pure arithmetic on the renderer's own exported layout and the engine's PlaceStage camera math.
// No rendering. Usage: node bounds.js <boardA> <boardB> <captions.json>
const m = require('./probe.cjs');
const fs = require('fs');
const [,, fa, fb, fcap] = process.argv;
const boards = {a: JSON.parse(fs.readFileSync(fa)), b: JSON.parse(fs.readFileSync(fb))};
const captions = JSON.parse(fs.readFileSync(fcap)).cues;
const manifest = require('/home/user/restore/TexasAIDispatch/video-engine/src/modern/placePlates.json');
const FPS = 30, FW = 1080, FH = 1920;
const OX = (manifest.plate.w - manifest.film.w) / 2, OY = (manifest.plate.h - manifest.film.h) / 2;
const ZOOM = {wide: 1, split: 1.04, medium: 1.08, close: 1.18, detail: 1.3, overhead: 1};
const clamp = v => Math.min(1, Math.max(0, v));
const lerp = (a, b, p) => a + (b - a) * p;
const ease = p => {const q = clamp(p); return q * q * q * (10 + q * (-15 + 6 * q));};
const raw = (s, e, t) => clamp((t - s) / (e - s));
const mixP = (a, b, p) => [lerp(a[0], b[0], p), lerp(a[1], b[1], p)];

// ---- 2D affine [a,b,c,d,e,f]: x' = a x + c y + e, y' = b x + d y + f ----
const I = [1, 0, 0, 1, 0, 0];
const mul = (A, B) => [A[0]*B[0]+A[2]*B[1], A[1]*B[0]+A[3]*B[1], A[0]*B[2]+A[2]*B[3], A[1]*B[2]+A[3]*B[3], A[0]*B[4]+A[2]*B[5]+A[4], A[1]*B[4]+A[3]*B[5]+A[5]];
const T = (x, y) => [1, 0, 0, 1, x, y];
const Sc = (s, sy = s) => [s, 0, 0, sy, 0, 0];
const R = deg => {const a = deg * Math.PI / 180; return [Math.cos(a), Math.sin(a), -Math.sin(a), Math.cos(a), 0, 0];};
const chain = (...ms) => ms.reduce((A, B) => mul(A, B), I);
const ap = (M, p) => [M[0]*p[0] + M[2]*p[1] + M[4], M[1]*p[0] + M[3]*p[1] + M[5]];
const corners = ([x0, y0, x1, y1]) => [[x0, y0], [x1, y0], [x1, y1], [x0, y1]];
const bbox = pts => [Math.min(...pts.map(p => p[0])), Math.min(...pts.map(p => p[1])), Math.max(...pts.map(p => p[0])), Math.max(...pts.map(p => p[1]))];
const boxTo = (M, b) => bbox(corners(b).map(p => ap(M, p)));
const cam = (f, s, a) => chain(T(a[0], a[1]), Sc(s), T(-f[0], -f[1]));
const overlap = (A, B) => A[0] < B[2] && B[0] < A[2] && A[1] < B[3] && B[1] < A[3];

// ---- the plate camera, PlaceStage's own arithmetic ----
function placeSubject(board, scene, shot, baseY, t) {
  const exterior = !scene.interior && shot.framing !== 'overhead' && !m.wallView(board, shot.view);
  if (!exterior) return I;
  const plate = m.plateFor(scene), c = plate.camera;
  const move = m.placePlate ? null : m.placeMove(plate, scene.camera_strategy, (t - scene.start_s) / scene.duration_s);
  const C = m.cardMatrix(c, m.groundDepthAt(c, baseY), move), z = ZOOM[shot.framing];
  // F = T(-O) Z(z; cx,cy) C T(O)
  const Cm = [C[0], C[3], C[1], C[4], C[2], C[5]];
  const Zm = [z, 0, 0, z, (1 - z) * c.cx, (1 - z) * c.cy];
  return chain(T(-OX, -OY), Zm, Cm, T(OX, OY));
}
// ---- the caption band and the disclosure chip ----
function bandTop(t) {
  const cue = captions.find(c => t >= c.start && t < c.end);
  if (!cue) return Infinity;
  const fit = m.captionLayout(cue.text, m.CAPTION_TEXT_WIDTH, cue.max_lines === 3 ? 3 : 2);
  return m.SAFE_BOTTOM - m.captionBandHeight(fit) - m.CAPTION_ENTRANCE_PX;
}
function chipRect(text) {
  const words = text.split(' '), lines = []; let cur = '';
  for (const w of words) {const n = cur ? cur + ' ' + w : w; if (cur && m.widthOf(n, 26, true) > 330) {lines.push(cur); cur = w;} else cur = n;}
  if (cur) lines.push(cur);
  return [44, 132, 44 + Math.max(...lines.map(l => m.widthOf(l, 26, true))) + 34, 132 + lines.length * 32 + 24];
}
const text = (x, y, size, s, bold = true) => [x, y - .74 * size, x + m.widthOf(s, size, bold), y + .24 * size];
function tagBox(pin, lines, shown, o) {
  const sc = o.scale ?? 1, size = o.size ?? 34, drop = o.drop ?? 26, side = o.side ?? 'right';
  const w = Math.max(...lines.map(l => m.widthOf(l, size, true))) + 40, h = lines.length * (size + 8) + 22;
  const x0 = side === 'right' ? -18 : -w + 18, e = ease(shown), swing = 10 * (1 - e) * (side === 'left' ? 1 : -1);
  const M = chain(T(pin[0], pin[1]), T(0, -40 * sc * (1 - e)), Sc(sc), R(swing));
  return boxTo(M, [x0, drop, x0 + w + 4, drop + h + 6]);
}

// ---- shots and frames ----
const shotsOf = (v, pred) => boards[v].film_direction.shots.filter(pred);
const sceneOf = (v, id) => boards[v].scenes.find(s => s.id === id);
const frames = shot => {const out = []; for (let f = Math.round(shot.start_s * FPS); f < Math.round((shot.start_s + shot.duration_s) * FPS); f++) out.push(f); return out;};
const W = v => m.actionWindows(boards[v].scenes);
const prog = (v, id, t) => m.actionProgress(W(v)[id], t);

const report = [];
function track(name) {
  const r = {name, frames: 0, minLeft: Infinity, minRight: Infinity, minTop: Infinity, minBandGap: Infinity, minFrameBottomGap: Infinity, chipHit: 0, other: {}};
  report.push(r); return r;
}
function rec(r, box, o = {}) {
  r.minLeft = Math.min(r.minLeft, box[0]); r.minRight = Math.min(r.minRight, FW - box[2]); r.minTop = Math.min(r.minTop, box[1]);
  r.minFrameBottomGap = Math.min(r.minFrameBottomGap, FH - box[3]);
  if (o.band !== undefined && o.band !== Infinity) r.minBandGap = Math.min(r.minBandGap, o.band - box[3]);
  if (o.chip && overlap(box, o.chip)) r.chipHit++;
}
const note = (r, k, v, fn = Math.min) => {r.other[k] = r.other[k] === undefined ? v : fn(r.other[k], v);};

// ===== B1: the phone-late banner =====
for (const v of ['a', 'b']) {
  const L = m.PHONE_LATE, B = m.bannerLayout(L.w, L.font), h = L.h;
  for (const shot of shotsOf(v, s => s.view === 'phone-late')) {
    const rows = B.rows.map((row, i) => track(`B1 ${v} ${shot.id} banner row "${row.text}" (screen)`));
    const ban = track(`B1 ${v} ${shot.id} banner rect (screen)`), body = track(`B1 ${v} ${shot.id} phone body (screen)`);
    const W3 = W(v)['s1-event-3'];
    for (const f of frames(shot)) {
      const t = f / FPS, b = m.actionProgress({...W3, end: W3.start + L.slide}, t);
      const bz = L.buzz.map(([a1, b1]) => clamp((t - W3.start - a1) / (b1 - a1))).find(q => q > 0 && q < 1) ?? 0;
      const shake = bz > 0 && bz < 1 ? 3 * Math.sin(2 * Math.PI * 9 * bz) * Math.sin(Math.PI * bz) : 0;
