      if (fig > 0) {rec(tr['98.82% figure'], boxTo(chain(C, T(40, 176), Sc(sfig), T(-40, -176)), text(40, 176, 84, '98.82%')), {band, chip}); tr['98.82% figure'].frames++;}
      const tagShown = clamp((r2 - .35) / .65);
      if (tagShown > 0) {rec(tr['assessments tag'], boxTo(PS, tagBox(tag.at, ['Initial assessments', 'after training'], tagShown, {side: 'right', drop: 30, scale: tag.s})), {band, chip}); tr['assessments tag'].frames++;}
      const s7e3 = prog(v, 's7-event-3', t), slide = ease(clamp(s7e3 / .8));
      if (slide >= 1) {
        const Rm = chain(PS, T(result.at[0], result.at[1]), Sc(result.s));
        rec(tr['result card at rest'], boxTo(Rm, [0, 0, 570, 434]), {band, chip}); tr['result card at rest'].frames++;
        rec(tr['Field result heading at rest'], boxTo(Rm, text(40, 74, 44, 'Field result')), {band, chip}); tr['Field result heading at rest'].frames++;
      }
    }
  }
  for (const shot of shotsOf(v, s => s.view === 'no-field-card')) {
    const sc = sceneOf(v, shot.scene_id), chip = chipRect(sc.production_disclosure), {card, tag, result, tech, stamp: ks} = m.S8;
    const tr = {}; for (const k of ['card body', 'heading', '98.82% figure', 'reported line', 'assessments tag', 'result card', 'Field result heading', 'None reported imprint', 'technician head', 'stamp', 'stamping arm'])
      tr[k] = track(`B3 ${v} ${shot.id} (${shot.framing}) s8 ${k}`);
