// Composed-transform frame-edge bounds for the R15h corrections, every frame of each affected shot in both
// treatments. Pure arithmetic on the renderer's own exported layout and the engine's PlaceStage camera math.
// No rendering. Usage: node bounds.js <boardA> <boardB> <captions.json>
const m = require('./probe.cjs');
const fs = require('fs');
const [,, fa, fb, fcap] = process.argv;
const boards = {a: JSON.parse(fs.readFileSync(fa)), b: JSON.parse(fs.readFileSync(fb))};
const captions = JSON.parse(fs.readFileSync(fcap)).cues;
const manifest = require('/home/user/restore/TexasAIDispatch/video-engine/src/modern/placePlates.json');
const FPS = 30, FW = 1080, FH = 1920;
const OX = (manifest.plate.w - manifest.film.w) / 2, OY = (manifest.plate.h - manifest.film.h) / 2;
const ZOOM = {wide: 1, split: 1.04, medium: 1.08, close: 1.18, detail: 1.3, overhead: 1};
const clamp = v => Math.min(1, Math.max(0, v));
const lerp = (a, b, p) => a + (b - a) * p;
const ease = p => {const q = clamp(p); return q * q * q * (10 + q * (-15 + 6 * q));};
const raw = (s, e, t) => clamp((t - s) / (e - s));
const mixP = (a, b, p) => [lerp(a[0], b[0], p), lerp(a[1], b[1], p)];

// ---- 2D affine [a,b,c,d,e,f]: x' = a x + c y + e, y' = b x + d y + f ----
const I = [1, 0, 0, 1, 0, 0];
const mul = (A, B) => [A[0]*B[0]+A[2]*B[1], A[1]*B[0]+A[3]*B[1], A[0]*B[2]+A[2]*B[3], A[1]*B[2]+A[3]*B[3], A[0]*B[4]+A[2]*B[5]+A[4], A[1]*B[4]+A[3]*B[5]+A[5]];
const T = (x, y) => [1, 0, 0, 1, x, y];
const Sc = (s, sy = s) => [s, 0, 0, sy, 0, 0];
const R = deg => {const a = deg * Math.PI / 180; return [Math.cos(a), Math.sin(a), -Math.sin(a), Math.cos(a), 0, 0];};
const chain = (...ms) => ms.reduce((A, B) => mul(A, B), I);
const ap = (M, p) => [M[0]*p[0] + M[2]*p[1] + M[4], M[1]*p[0] + M[3]*p[1] + M[5]];
const corners = ([x0, y0, x1, y1]) => [[x0, y0], [x1, y0], [x1, y1], [x0, y1]];
const bbox = pts => [Math.min(...pts.map(p => p[0])), Math.min(...pts.map(p => p[1])), Math.max(...pts.map(p => p[0])), Math.max(...pts.map(p => p[1]))];
const boxTo = (M, b) => bbox(corners(b).map(p => ap(M, p)));
const cam = (f, s, a) => chain(T(a[0], a[1]), Sc(s), T(-f[0], -f[1]));
const overlap = (A, B) => A[0] < B[2] && B[0] < A[2] && A[1] < B[3] && B[1] < A[3];

// ---- the plate camera, PlaceStage's own arithmetic ----
function placeSubject(board, scene, shot, baseY, t) {
  const exterior = !scene.interior && shot.framing !== 'overhead' && !m.wallView(board, shot.view);
  if (!exterior) return I;
  const plate = m.plateFor(scene), c = plate.camera;
