  const w = Math.max(...lines.map(l => m.widthOf(l, size, true))) + 40, h = lines.length * (size + 8) + 22;
  const x0 = side === 'right' ? -18 : -w + 18, e = ease(shown), swing = 10 * (1 - e) * (side === 'left' ? 1 : -1);
  const M = chain(T(pin[0], pin[1]), T(0, -40 * sc * (1 - e)), Sc(sc), R(swing));
  return boxTo(M, [x0, drop, x0 + w + 4, drop + h + 6]);
}

// ---- shots and frames ----
