      const bz = L.buzz.map(([a1, b1]) => clamp((t - W3.start - a1) / (b1 - a1))).find(q => q > 0 && q < 1) ?? 0;
      const shake = bz > 0 && bz < 1 ? 3 * Math.sin(2 * Math.PI * 9 * bz) * Math.sin(Math.PI * bz) : 0;
