// Static-markup smoke of the flood-station episode: every frame of both treatments renders to an SVG string
// without throwing, without NaN/Infinity in any attribute, and identically when rendered twice (random access).
// No frames, stills or pixels are produced; PlaceStage runs in its probe mode, which draws no images.
import fs from 'node:fs';
import path from 'node:path';
import {createRequire} from 'node:module';
import {build} from '/home/user/restore/TexasAIDispatch/video-engine/node_modules/esbuild/lib/main.js';
const engine = '/home/user/restore/TexasAIDispatch/video-engine';
const here = '/tmp/claude-0/-home-user/f36491ea-e3a6-5408-8e5d-7e435fd659ae/scratchpad/harness';
const [,, fa, fb] = process.argv;
const outfile = path.join(here, 'smoke.cjs');
await build({stdin: {contents: "export {FloodStationFilm} from './src/modern/episodes/2026-10-15/FloodStationFilm'; export {PlaceStage} from './src/modern/PlaceStage'; export {ArtDirectionProvider} from './src/lib/artDirection'; export {filmShotAt} from './src/modern/DirectedFilm';", resolveDir: engine},
  outfile, bundle: true, platform: 'node', format: 'cjs', packages: 'external', logLevel: 'silent', jsx: 'automatic'});
const require = createRequire(engine + '/package.json');
const React = require('react');
const remotionPath = require.resolve('remotion'), remotion = require(remotionPath);
let FRAME = 0;
require.cache[remotionPath].exports = {...remotion, useCurrentFrame: () => FRAME, useVideoConfig: () => ({fps: 30, width: 1080, height: 1920, durationInFrames: 2000})};
const api = require(outfile);
const {renderToStaticMarkup} = require('react-dom/server');
let failures = 0;
for (const [label, file] of [['a', fa], ['b', fb]]) {
  const board = {...JSON.parse(fs.readFileSync(file, 'utf8')), __placeProbe: true};
  const plan = board.film_direction, end = Math.round(Math.max(...board.scenes.map(s => s.start_s + s.duration_s)) * 30);
  const draw = f => {
    FRAME = f; const t = f / 30, shot = api.filmShotAt(plan, t, 30), scene = board.scenes.find(s => s.id === shot.scene_id);
    return renderToStaticMarkup(React.createElement(api.ArtDirectionProvider, {profile: board.art_direction},
      React.createElement(api.PlaceStage, {board, scene, shot, time_s: t},
        React.createElement(api.FloodStationFilm, {board, scene, shot, time_s: t, shot_s: t - shot.start_s, variant: plan.variant}))));
  };
  let n = 0, bad = 0;
  for (let f = 0; f < end; f++) {
    try {
      const svg = draw(f);
      if (/NaN|Infinity/.test(svg)) {bad++; if (bad < 4) console.log(label, 'frame', f, 'contains NaN or Infinity');}
      n++;
    } catch (e) {bad++; if (bad < 4) console.log(label, 'frame', f, 'threw', e.message);}
  }
  // random access: out-of-order frames equal their in-order render
  const probe = [end - 1, 0, 1671, 600, 1500, 1200, 250, 1700, 1440, 1563];
  const first = probe.map(draw), again = [...probe].reverse().map(draw).reverse();
  const det = first.every((s, i) => s === again[i]);
  console.log(`treatment ${label}: ${n} of ${end} frames rendered to markup, ${bad} problems, random-access deterministic: ${det}`);
  failures += bad + (det ? 0 : 1);
}
process.exit(failures ? 1 : 0);

