// Longest runs of consecutive frames whose markup is byte-identical (a static picture), per treatment.
const canon = svg => {const ids = [...svg.matchAll(/ id="([^"]+)"/g)].map(x => x[1]); let out = svg; [...new Set(ids)].forEach((id, k) => {out = out.split(`"${id}"`).join(`"ID${k}"`).split(`#${id})`).join(`#ID${k})`);}); return out;};
for (const [label, file] of [["a", fa], ["b", fb]]) {
  const board = {...JSON.parse(fs.readFileSync(file, "utf8")), __placeProbe: true};
  const plan = board.film_direction, end = Math.round(Math.max(...board.scenes.map(s => s.start_s + s.duration_s)) * 30);
  const draw = f => {FRAME = f; const t = f / 30, shot = api.filmShotAt(plan, t, 30), scene = board.scenes.find(s => s.id === shot.scene_id);
    return [shot.id, canon(renderToStaticMarkup(React.createElement(api.ArtDirectionProvider, {profile: board.art_direction}, React.createElement(api.PlaceStage, {board, scene, shot, time_s: t}, React.createElement(api.FloodStationFilm, {board, scene, shot, time_s: t, shot_s: t - shot.start_s, variant: plan.variant})))))];};
  let prev = null, start = 0, runs = [];
  for (let f = 0; f <= end; f++) {const cur = f < end ? draw(f) : [null, null]; if (!prev || cur[1] !== prev[1]) {if (prev) runs.push({shot: prev[0], from: (start / 30).toFixed(2), to: (f / 30).toFixed(2), s: (f - start) / 30}); start = f;} prev = cur;}
  runs.sort((x, y) => y.s - x.s);
  console.log(label, JSON.stringify(runs.slice(0, 8)));
}
EOF
